declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$WRD$q$,$q$WeRide$q$,null,null,true,false,array[$q$US$q$,$q$HKEX$q$]::text[],$q$Nasdaq; HKEX 0800$q$,$q$CN$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$AiDriver$q$,$q$private_company$q$),($q$Alliance Automotive R&D (Shanghai)$q$,$q$private_company$q$),($q$Alliance Automotive Research & Development (Shanghai)$q$,$q$private_company$q$),($q$Alliance Ventures$q$,$q$private_company$q$),($q$Alliance affiliates$q$,$q$private_company$q$),($q$Baiyun Taxi Group$q$,$q$private_company$q$),($q$Bosch$q$,$q$public_company$q$),($q$Chery$q$,$q$private_company$q$),($q$Dubai Roads and Transport Authority$q$,$q$institution$q$),($q$ELEVATE Slovakia$q$,$q$private_company$q$),($q$Ecar Tech$q$,$q$private_company$q$),($q$GAC$q$,$q$public_company$q$),($q$GAC Capital International$q$,$q$private_company$q$),($q$Geely Farizon$q$,$q$private_company$q$),($q$Get Ride$q$,$q$private_company$q$),($q$Golden Dragon$q$,$q$private_company$q$),($q$Grab$q$,$q$public_company$q$),($q$Guangqizhixing Holdings$q$,$q$private_company$q$),($q$Guangzhou Yuji$q$,$q$private_company$q$),($q$Hyundai$q$,$q$public_company$q$),($q$JMC-Ford Motors$q$,$q$private_company$q$),($q$JSC International Investment Fund SPC$q$,$q$private_company$q$),($q$Lenovo Vehicle Computing$q$,$q$private_company$q$),($q$NVIDIA$q$,$q$public_company$q$),($q$Nissan$q$,$q$public_company$q$),($q$Nissan Mobility Service$q$,$q$private_company$q$),($q$Ourland Environmental Technical$q$,$q$private_company$q$),($q$Qiming$q$,$q$private_company$q$),($q$Renault$q$,$q$public_company$q$),($q$Uber$q$,$q$public_company$q$),($q$Yuji$q$,$q$private_company$q$),($q$Yutong$q$,$q$private_company$q$),($q$Yutong Bus$q$,$q$public_company$q$),($q$Yutong entities$q$,$q$private_company$q$),($q$Zhengzhou Yutong Heavy Industries$q$,$q$private_company$q$),($q$ioki$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$A vehicle purchase agreement with Zhengzhou Yutong Bus Co., Ltd. (“Yutong”), an affiliate of a shareholder of the Company, pursuant to which the Group committed to purchase vehicles manufactured by Yutong with an aggregated purchase amount of RMB   100.3    million in 2024.$q$),(2,$q$Additionally, for the years ended December 31, 2023 and 2024, we purchased goods from Ourland Environmental Technical Ltd. in an aggregate amount of nil, RMB0.8 million (US$0.1 million), respectively.$q$),(3,$q$Alliance Ventures B.V. (12) 63,680,080 — 6.3 4.2$q$),(4,$q$Co-operation Agreement between the Registrant and Renault s.a.s., dated July 17, 2024$q$),(5,$q$Cooperation Agreement between Bosch Automotive Products (Suzhou) Co., Ltd. and WFOE, dated May 24, 2022$q$),(6,$q$English translation of Form of Agreement on Vehicle Purchase between Yutong Bus Co., Ltd. and WFOE, and a schedule of all executed Agreements on Vehicle Purchase adopting the same form$q$),(7,$q$Equity Commitment Letter between the Registrant and Uber Technologies, Inc., dated May 5, 2025$q$),(8,$q$For example, we entered into a strategic partnership with Bosch in 2022 under which we, as a Tier 2 supplier, provide research and development services, key technologies and ecosystem support.$q$),(9,$q$For example, we have received investment commitments from ride-hailing giants such as Uber and Grab, highlighting our strategic position and leading role in the industry.$q$),(10,$q$For the year ended December 31, 2024, we provided services to Zhengzhou Yutong Heavy Industries Co., Ltd. with an aggregate amount of RMB189 thousand.$q$),(11,$q$For the years ended December 31 2023, 2024 and 2025, we provided services to Alliance Automotive R&D (Shanghai) Co., Ltd., an affiliate of our shareholder, Alliance Ventures B.V., with an aggregate amount of RMB9.2 million, RMB7.9 million and RMB60.8 thousand (US$8.7 thousand), respectively.$q$),(12,$q$For the years ended December 31, 2023 and 2024, we provided services to Ourland Environmental Technical Ltd. with an aggregate amount of nil and RMB11.1 million, respectively.$q$),(13,$q$For the years ended December 31, 2023 and 2024, we purchased goods from Yutong Bus Co., Ltd. with an aggregate amount of RMB18.4 million and RMB71.0 million, respectively.$q$),(14,$q$For the years ended December 31, 2023 and 2024, we purchased goods from Zhengzhou Yutong Heavy Industries Co., Ltd., an affiliate of the Yutong entities, with an aggregate amount of nil and RMB3.0 million, respectively.$q$),(15,$q$For the years ended December 31, 2023 and 2024, we sold goods to Yutong Bus Co., Ltd., an affiliate of our shareholder, the Yutong entities, with an aggregate amount of RMB5.7 million and nil, respectively.$q$),(16,$q$For the years ended December 31, 2023, 2024 and 2025, Guangzhou Yuji provided surveying and mapping services to our company in the amount of RMB111.5 million, RMB90.1 million and RMB66.8 million (US$9.6 million), respectively.$q$),(17,$q$For the years ended December 31, 2023, 2024 and 2025, we provided services to Guangzhou Yuji in the amount of nil, RMB528 thousand and nil, respectively.$q$),(18,$q$For the years ended December 31, 2023, 2024 and 2025, we provided services to Nissan Mobility Service Co., Ltd with an aggregate amount of RMB5.7 million, RMB7.1 million and RMB7.6 million (US$1.1 million), respectively.$q$),(19,$q$Goods Purchase Agreement between Alliance Automotive Research & Development (Shanghai) Co., Ltd. and WFOE, dated July 31, 2023$q$),(20,$q$In 2025, we deepened our collaboration with Geely Farizon to deliver the next-generation robotaxi GXR as a purpose-built, factory pre-installed autonomous vehicle—eliminating post-production retrofitting and delivering higher safety consistency, lower unit costs and faster assembly.$q$),(21,$q$In 2026, our one‑stage end‑to‑end ADAS solution, jointly developed with Bosch, has achieved four consecutive championship wins in the Second China Urban Intelligent Driving Competition, making WeRide WRD 3.0 the first and only solution in the competition’s history to secure this record and underscoring its breakthrough leadership in complex urban driving environments.$q$),(22,$q$In December 2025, we launched public robotaxi passenger rides in Dubai in partnership with Uber and Dubai’s Roads and Transport Authority (RTA), with riders able to book through the “Autonomous” option on the Uber app.$q$),(23,$q$In March 2026, we entered Slovakia through a strategic partnership with ELEVATE Slovakia to deploy autonomous vehicles including robotaxi, robobus, robovan, and robosweeper, launching the country’s first autonomous vehicle program and Europe’s first large-scale, multi-product autonomous driving commercial deployment, bringing our global footprint to over 40 cities across 12 countries.$q$),(24,$q$In Southeast Asia, in March 2026, we officially commenced public operations of the Ai.R (Autonomously Intelligent Ride) service in Punggol with Grab, marking the first deployment of an autonomous passenger service in a residential estate in Singapore.$q$),(25,$q$In addition, we also provide ADAS and research and development services to Bosch and autonomous driving research and development services to Nissan.$q$),(26,$q$In our Bosch partnership, we provide leading ADAS tec$q$),(27,$q$Our L2+ ADAS,  WePilot 3.0 , has been adopted by OEMs and Tier-1 suppliers, including Chery, GAC, and Bosch, across multiple vehicle models.$q$),(28,$q$Pursuant to the agreement, Guangzhou Yuji provides certain mapping and data services to us and our subsidiaries for ordinary business purposes, including high-precision map collection, production and manufacturing services, as well as data collection and compliance services.$q$),(29,$q$Qiming entities (11) 62,865,042 — 6.3 4.2$q$),(30,$q$Represents (i) 34,573,269 Class A ordinary shares directly owned by Alliance Ventures B.V., (ii) 10,616,604 Class A ordinary shares beneficially owned by Renault s.a.s., and Renault S.A., and (iii) 18,490,206 Class A ordinary shares beneficially owned by Nissan Motor Co., Ltd., as reported on the Schedule 13D/A filed by Alliance Ventures B.V., Renault s.a.s., Renault S.A. and Nissan Motor Co., Ltd. on October 29, 2025.$q$),(31,$q$Represents 23,038,300 Class A ordinary shares and 33,579,966 Class A ordinary shares represented by 11,193,322 ADSs held by SMB Holding Corporation, a wholly-owned subsidiary of Uber Technologies, Inc., a publicly traded company.$q$),(32,$q$Share Subscription Agreement between the Registrant and Alliance Ventures, B.V., dated July 26, 2024 and as amended on October 21, 2024$q$),(33,$q$Subscription Agreement between the Registrant and Get Ride Inc., dated August 8, 2024$q$),(34,$q$Subscription Agreement between the Registrant and JSC International Investment Fund SPC, dated August 9, 2024$q$),(35,$q$Subscription Agreement between the Registrant, Guangqizhixing Holdings Limited and Gac Capital International Ltd., dated July 17, 2024$q$),(36,$q$Such ecosystem partners include Uber, AiDriver, Baiyun Taxi Group, NVIDIA, Lenovo Vehicle Computing, ioki, Grab and ELEVATE Slovakia.$q$),(37,$q$The Group entered into a share subscription agreement with one of Alliance affiliates in July 2024, who committed to subscribe shares of the Company as a cornerstone investor with an aggregate purchase price of USD   97.0    million (equivalent to RMB   689.6    million).$q$),(38,$q$This information is based on the information reported on the Schedule 13G filed by the Qiming entities (as defined below) on February 10, 2025.$q$),(39,$q$This information is based on the information reported on the Schedule 13G/A filed by the Yutong entities (as defined below) on February 13, 2026.$q$),(40,$q$Uber Technologies, Inc (13) 56,618,266 — 5.6 3.8$q$),(41,$q$We are also working with our partners, such as Hyundai, to promote sustainable mobility and the adoption of clean energy.$q$),(42,$q$We currently collaborate with Guangzhou Yuji Technology Co., Ltd., or Guangzhou Yuji, a service provider that possesses a navigation electronic map production and surveying license, to provide surveying and mapping services to our company. Under the cooperation, the service provider provides us with HD maps services to complement the vision of our sensors.$q$),(43,$q$We currently partner with Yutong and Ecar Tech to manufacture our robosweepers.$q$),(44,$q$We partner with JMC-Ford Motors and Ecar Tech to manufacture our robovans.$q$),(45,$q$We partner with Yutong and Golden Dragon to produce robobuses.$q$),(46,$q$We provide ADAS and research and development services to Bosch.$q$),(47,$q$Yutong entities (10) 65,659,592 — 6.5 4.4$q$),(48,$q$a decrease in amounts due to related parties of RMB68.4 million for settlement of purchase orders to Yutong affiliates and Yuji affiliates$q$),(49,$q$including (i) US$97 million by Alliance Ventures B.V., or Alliance Ventures, the venture capital fund of the Renault Nissan Mitsubishi Alliance, and (ii) US$20 million by Guangqizhixing Holdings Limited and Gac Capital International Ltd.$q$),(50,$q$most notably our collaboration with Uber and Grab to scale robotaxi services across additional international markets.$q$);
