create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Lyft$q$ then ticker=$q$LYFT$q$ when $q$DoorDash$q$ then ticker=$q$DASH$q$ when $q$WRD$q$ then ticker=$q$WRD$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$WRD FY2025 20-F (M15)$q$,'claude-sonnet-5-5 via Claude Code session',1.9406,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2025-12-31$q$::date end,$q$sec_filing$q$,$q$staged$q$,null,run_id,$q$2025-12-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1867729/000110465926047323/wrd-20251231x20f.htm$q$,r.sec[k],t,true,$q$2026-04-23$q$::date from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
